contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMin) public payable {
        bool reverted;
        c.SetMinSum(newMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterMin = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(!reverted && afterMin == newMin);
    }

    receive() external payable {}
}

