pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 newMin) internal {
        bool reverted;
        try c.SetMinSum(newMin) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterMin;
        try c.MinSum() returns (uint256 __r) { afterMin = __r; } catch { return; }
        assertTrue(!reverted && afterMin == newMin);
    }

    function testFuzz_run(uint256 newMin) public {
        _run(newMin);
    }

    receive() external payable {}
}
